  InputGroup,
} from "react-bootstrap";

function History() {
  // --- 1. เตรียมข้อมูลตัวเลือก ---
  const monthsThai = [
    { val: "01", name: "มกราคม" }, { val: "02", name: "กุมภาพันธ์" },
    { val: "03", name: "มีนาคม" }, { val: "04", name: "เมษายน" },
    { val: "05", name: "พฤษภาคม" }, { val: "06", name: "มิถุนายน" },
    { val: "07", name: "กรกฎาคม" }, { val: "08", name: "สิงหาคม" },
    { val: "09", name: "กันยายน" }, { val: "10", name: "ตุลาคม" },
    { val: "11", name: "พฤศจิกายน" }, { val: "12", name: "ธันวาคม" }
  ];
  
  const currentYearCE = new Date().getFullYear();
  const yearsBE = [currentYearCE + 542, currentYearCE + 543, currentYearCE + 544];
  const timeOptions = [];
  for (let h = 7; h <= 22; h++) {
    timeOptions.push(`${h.toString().padStart(2, '0')}:00`);
  }

  // --- 2. State ---
  const [selectedDay, setSelectedDay] = useState(new Date().getDate().toString());
  const [selectedMonth, setSelectedMonth] = useState((new Date().getMonth() + 1).toString().padStart(2, '0'));
  const [selectedYearBE, setSelectedYearBE] = useState((currentYearCE + 543).toString());
  const [startTime, setStartTime] = useState("07:00");
  const [endTime, setEndTime] = useState("22:00");
  const [cameraId, setCameraId] = useState("CAM01");
  const [data, setData] = useState({ labels: [], series: [] });
  const [loading, setLoading] = useState(false);

  // --- 3. Dynamic Days Logic ---
  const daysCount = new Date(parseInt(selectedYearBE) - 543, parseInt(selectedMonth), 0).getDate();
  const daysArray = Array.from({ length: daysCount }, (_, i) => (i + 1).toString());

  useEffect(() => {
    if (parseInt(selectedDay) > daysCount) setSelectedDay(daysCount.toString());
  }, [selectedMonth, selectedYearBE, daysCount, selectedDay]);

  // --- 4. Fetch Data ---
  const handleSearch = async () => {
    setLoading(true);
    const yearCE = parseInt(selectedYearBE) - 543;
    const formattedDate = `${yearCE}-${selectedMonth}-${selectedDay.padStart(2, '0')}`;

    try {
      const res = await fetch(
        `http://localhost:3000/api/history?cameraId=${cameraId}&date=${formattedDate}&startTime=${startTime}&endTime=${endTime}`
      );
      const result = await res.json();
      if (result.labels) {
        setData({ 
          labels: result.labels.map(l => l + " น."), 
          series: result.series 
        });
      }
    } catch (err) {
      console.error("Fetch Error:", err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Container fluid>
      <Row>
        <Col md="12">
          <Card className="card-plain">
            <Card.Header>
              <Card.Title as="h4" className="font-weight-bold">
                <i className="nc-icon nc-zoom-split mr-2"></i> ตัวเลือกการค้นหาประวัติ
              </Card.Title>
              <p className="card-category">ระบุสถานีและช่วงเวลาที่ต้องการตรวจสอบข้อมูลผู้โดยสาร</p>
            </Card.Header>
            <Card.Body>
              <Row className="align-items-center bg-white p-4 rounded shadow-sm mx-0">
                {/* เลือกจุดจอด */}
                <Col lg="3" md="6" className="mb-3 mb-lg-0">
                  <Form.Group className="mb-0">
                    <label className="text-uppercase font-weight-bold small text-muted">จุดจอดรถ / สถานี</label>
                    <InputGroup>
                      <InputGroup.Prepend>
                        <InputGroup.Text className="bg-light border-right-0"><i className="nc-icon nc-bus-front-12"></i></InputGroup.Text>
                      </InputGroup.Prepend>
                      <Form.Control as="select" className="border-left-0 pl-0" value={cameraId} onChange={(e) => setCameraId(e.target.value)}>
                        <option value="CAM01">วิศวะ (CAM01)</option>
                        <option value="CAM02">วิทยาศาสตร์ (CAM02)</option>
                        <option value="CAM03">ศิลปศาสตร์ (CAM03)</option>
                        <option value="CAM04">หอพัก PKY (CAM04)</option>
                      </Form.Control>
                    </InputGroup>
                  </Form.Group>
                </Col>

                {/* เลือกวันที่/เดือน/ปี */}
                <Col lg="4" md="6" className="mb-3 mb-lg-0">
                  <label className="text-uppercase font-weight-bold small text-muted">วันที่เดินทาง (พ.ศ.)</label>
                  <div className="d-flex border rounded bg-light p-1">
                    <Form.Control as="select" variant="link" className="border-0 bg-transparent" value={selectedDay} onChange={(e) => setSelectedDay(e.target.value)}>
                      {daysArray.map(d => <option key={d} value={d}>{d}</option>)}
                    </Form.Control>
                    <Form.Control as="select" variant="link" className="border-0 bg-transparent" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}>
                      {monthsThai.map(m => <option key={m.val} value={m.val}>{m.name}</option>)}
                    </Form.Control>
                    <Form.Control as="select" variant="link" className="border-0 bg-transparent" value={selectedYearBE} onChange={(e) => setSelectedYearBE(e.target.value)}>
                      {yearsBE.map(y => <option key={y} value={y}>{y}</option>)}
                    </Form.Control>
                  </div>
                </Col>

                {/* เลือกช่วงเวลา */}
                <Col lg="3" md="8" className="mb-3 mb-lg-0">
                  <label className="text-uppercase font-weight-bold small text-muted">ช่วงเวลา (24 ชม.)</label>
                  <div className="d-flex align-items-center border rounded bg-light p-1">
                    <Form.Control as="select" className="border-0 bg-transparent" value={startTime} onChange={(e) => setStartTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                    </Form.Control>
                    <span className="mx-2 text-muted">ถึง</span>
                    <Form.Control as="select" className="border-0 bg-transparent" value={endTime} onChange={(e) => setEndTime(e.target.value)}>
                      {timeOptions.map(t => <option key={t} value={t}>{t}</option>)}
                    </Form.Control>
                  </div>
                </Col>

                {/* ปุ่มค้นหา */}
                <Col lg="2" md="4">
                  <Button className="btn-fill w-100 mt-lg-4" variant="info" onClick={handleSearch} disabled={loading}>
                    {loading ? <i className="fa fa-spinner fa-spin mr-2"></i> : <i className="nc-icon nc-zoom-split mr-2"></i>}
                    ค้นหา
                  </Button>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* กราฟแสดงผลแบบ Modern */}
      {data.labels.length > 0 && (
        <Row className="mt-4">
          <Col md="12">
            <Card className="card-chart shadow">
              <Card.Header>
                <div className="d-flex justify-content-between align-items-center px-3">
                  <div>
                    <Card.Title as="h4" className="text-primary font-weight-bold">
                      <i className="nc-icon nc-chart-bar-32 mr-2"></i> สถิติจำนวนคน: {cameraId}
                    </Card.Title>
                    <p className="card-category">
                      ประจำวันที่ {selectedDay} {monthsThai.find(m => m.val === selectedMonth).name} {selectedYearBE}
                    </p>
                  </div>
                  <div className="text-right d-none d-sm-block">
                    <h5 className="mb-0 text-info font-weight-bold">{startTime} - {endTime} น.</h5>
                    <small className="text-muted">ช่วงเวลาที่แสดง</small>
                  </div>
                </div>
              </Card.Header>
              <Card.Body>
                <div className="ct-chart px-2" style={{ height: "350px" }}>
                  <ChartistGraph
                    data={data}
                    type="Line"
                    options={{
                      low: 0,
                      showArea: true,
                      fullWidth: true,
                      lineSmooth: true,
                      chartPadding: { right: 40 },
                      axisX: { showGrid: false },
                    }}
                  />
                </div>
              </Card.Body>
              <Card.Footer>
                <div className="legend ml-3">
                  <i className="fas fa-circle text-info"></i> จำนวนผู้โดยสาร (คน) &nbsp;
                  <i className="fas fa-history text-muted ml-3"></i> ข้อมูลประวัติจากฐานข้อมูล
                </div>
                <hr />
                <div className="stats ml-3 text-muted pb-3">
                  <i className="nc-icon nc-time-alarm mr-1"></i> ข้อมูลอัปเดตล่าสุด ณ วันที่ค้นหา
                </div>
              </Card.Footer>
            </Card>
          </Col>
        </Row>
      )}
    </Container>
  );
}

export default History;
